local BoltLatchMaker = {}
local PRODUCTS = {
    iron_bolt = { name = "Železen zavor", ironCost = 1, time = 1, cost = 4, security = 4, description = "Preprost železen zavor za vrata." },
    latch = { name = "Zasuk", ironCost = 1, time = 2, cost = 12, security = 6, prestige = 1, description = "Zasuk za notranja vrata." },
    brass_bolt = { name = "Medeninast zavor", brassCost = 2, time = 3, cost = 30, security = 10, prestige = 2, description = "Medeninast zavor z okrasjem." },
    deadbolt = { name = "Mrtvi zavor", steelCost = 1, ironCost = 1, time = 4, cost = 70, security = 16, prestige = 4, description = "Težek jeklen mrtvi zavor za okrepitev." },
    silver_latch = { name = "Srebrni zasuk", silverCost = 2, time = 5, cost = 155, security = 20, prestige = 9, happiness = 1, description = "Srebrni zasuk za zakladne sobe." },
    royal_ceremonial_bolt = { name = "Kraljevski slovesni zavor", goldCost = 2, silverCost = 2, steelCost = 1, jewelCost = 1, time = 8, cost = 440, security = 32, prestige = 24, happiness = 5, description = "Slovesni zavor z draguljnim grbom za kraljevske dvorane." },
}
local BUILDINGS = {
    workshop = { name = "Zavorska delavnica", cost = { gold = 190, wood = 100 }, upkeep = 4, qualityBonus = 5 },
    forge = { name = "Zavorska kovačija", cost = { gold = 650, wood = 200, stone = 150 }, upkeep = 16, qualityBonus = 15 },
    filing_room = { name = "Brusilnica", cost = { gold = 1100, wood = 250, stone = 250, silver = 20 }, upkeep = 26, qualityBonus = 22 },
    royal_bolt_atelier = { name = "Kraljevski atelje zavorov", cost = { gold = 3200, wood = 400, stone = 500, gold = 30 }, upkeep = 62, qualityBonus = 36, prestigeBonus = 18 },
}
BoltLatchMaker.ironStock = 14; BoltLatchMaker.steelStock = 10; BoltLatchMaker.brassStock = 6; BoltLatchMaker.silverStock = 4; BoltLatchMaker.goldStock = 3; BoltLatchMaker.jewelStock = 3
BoltLatchMaker.productStock = {}; BoltLatchMaker.buildings = {}; BoltLatchMaker.maker = nil; BoltLatchMaker.activeMaking = {}; BoltLatchMaker.totalProducts = 0; BoltLatchMaker.dayTimer = 0
function BoltLatchMaker.init() BoltLatchMaker.ironStock=14; BoltLatchMaker.steelStock=10; BoltLatchMaker.brassStock=6; BoltLatchMaker.silverStock=4; BoltLatchMaker.goldStock=3; BoltLatchMaker.jewelStock=3; BoltLatchMaker.productStock={}; BoltLatchMaker.buildings={}; BoltLatchMaker.maker=nil; BoltLatchMaker.activeMaking={}; BoltLatchMaker.totalProducts=0; BoltLatchMaker.dayTimer=0; print("[BoltLatchMaker] Royal Bolt & Latch Maker System initialized (6 products, 4 buildings)") end
function BoltLatchMaker.hireMaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BoltLatchMaker.maker={name=n or ("Zavorar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zavorar najet: %s (spretnost: %d)",BoltLatchMaker.maker.name,s),"success") end; return true end
function BoltLatchMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BoltLatchMaker.build(id) local ok,e=BoltLatchMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BoltLatchMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BoltLatchMaker.getQualityBonus() local b=0; for _,bd in ipairs(BoltLatchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BoltLatchMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BoltLatchMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and BoltLatchMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and BoltLatchMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and BoltLatchMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BoltLatchMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BoltLatchMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BoltLatchMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BoltLatchMaker.maker then return false,"Potreben zavorar" end; return true end
function BoltLatchMaker.make(pt,qty) qty=qty or 5; local ok,e=BoltLatchMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BoltLatchMaker.ironStock=BoltLatchMaker.ironStock-d.ironCost*qty end; if d.steelCost then BoltLatchMaker.steelStock=BoltLatchMaker.steelStock-d.steelCost*qty end; if d.brassCost then BoltLatchMaker.brassStock=BoltLatchMaker.brassStock-d.brassCost*qty end; if d.silverCost then BoltLatchMaker.silverStock=BoltLatchMaker.silverStock-d.silverCost*qty end; if d.goldCost then BoltLatchMaker.goldStock=BoltLatchMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BoltLatchMaker.jewelStock=BoltLatchMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BoltLatchMaker.maker then t=math.max(1,t-math.floor(BoltLatchMaker.maker.skill/15)) end; table.insert(BoltLatchMaker.activeMaking,{id="bolt_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,security=d.security or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BoltLatchMaker.completeMaking(m) local q=1.0+(BoltLatchMaker.getQualityBonus()/100); if BoltLatchMaker.maker then q=q+(BoltLatchMaker.maker.skill/200) end; q=math.min(2.0,q); BoltLatchMaker.productStock[m.productType]=(BoltLatchMaker.productStock[m.productType] or 0)+m.quantity; BoltLatchMaker.totalProducts=BoltLatchMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BoltLatchMaker.maker then BoltLatchMaker.maker.itemsMade=BoltLatchMaker.maker.itemsMade+m.quantity; if math.random()<0.15 then BoltLatchMaker.maker.skill=math.min(100,BoltLatchMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zavori izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end end
function BoltLatchMaker.update(dt) if not _G.state then return end; BoltLatchMaker.dayTimer=BoltLatchMaker.dayTimer+dt; if BoltLatchMaker.dayTimer>=30 then BoltLatchMaker.dayTimer=0; for i=#BoltLatchMaker.activeMaking,1,-1 do local m=BoltLatchMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BoltLatchMaker.completeMaking(m); table.remove(BoltLatchMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BoltLatchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BoltLatchMaker.maker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BoltLatchMaker.getStats() return {ironStock=BoltLatchMaker.ironStock,steelStock=BoltLatchMaker.steelStock,brassStock=BoltLatchMaker.brassStock,silverStock=BoltLatchMaker.silverStock,goldStock=BoltLatchMaker.goldStock,jewelStock=BoltLatchMaker.jewelStock,productStock=BoltLatchMaker.productStock,numBuildings=#BoltLatchMaker.buildings,hasMaker=BoltLatchMaker.maker~=nil,makerName=BoltLatchMaker.maker and BoltLatchMaker.maker.name or "—",makerSkill=BoltLatchMaker.maker and BoltLatchMaker.maker.skill or 0,activeMaking=#BoltLatchMaker.activeMaking,totalProducts=BoltLatchMaker.totalProducts} end
return BoltLatchMaker
